import { Autopay, BillingFailure } from "../domain/autopay";

export class AutopayRepository {
  private readonly rows = new Map<string, Autopay>();
  private readonly failures: BillingFailure[] = [];
  private seq = 0;

  create(input: Omit<Autopay, "id" | "active">): Autopay {
    this.seq++;
    const a: Autopay = { ...input, id: `AP${String(this.seq).padStart(5, "0")}`, active: true };
    this.rows.set(a.id, a);
    return { ...a };
  }

  find(id: string): Autopay | undefined {
    const a = this.rows.get(id);
    return a ? { ...a } : undefined;
  }

  deactivate(id: string): void {
    const a = this.rows.get(id);
    if (a) a.active = false;
  }

  /** 해당 출금일에 출금되는 활성 계약 — 등록 순 */
  billingOn(day: number): Autopay[] {
    return [...this.rows.values()].filter((a) => a.active && a.billingDay === day).map((a) => ({ ...a }));
  }

  addFailure(f: BillingFailure): void {
    this.failures.push({ ...f });
  }

  failuresOf(autopayId: string): BillingFailure[] {
    return this.failures.filter((f) => f.autopayId === autopayId).map((f) => ({ ...f }));
  }
}
import { Member } from "../domain/member";

export class MemberRepository {
  private readonly rows = new Map<string, Member>();

  save(m: Member): Member {
    this.rows.set(m.id, { ...m });
    return m;
  }

  find(id: string): Member | undefined {
    const m = this.rows.get(id);
    return m ? { ...m } : undefined;
  }

  all(): Member[] {
    return [...this.rows.values()].map((m) => ({ ...m }));
  }
}
import { Reminder } from "../domain/reminder";
import { LocalDate } from "../time/localTime";

/** 예약해 둔 알림 — 키 단위로 한 번만 저장된다. */
export class ReminderRepository {
  private readonly rows = new Map<string, Reminder>();

  has(key: string): boolean {
    return this.rows.has(key);
  }

  save(r: Reminder): void {
    this.rows.set(r.key, { ...r });
  }

  find(key: string): Reminder | undefined {
    const r = this.rows.get(key);
    return r ? { ...r } : undefined;
  }

  byPlanDate(date: LocalDate): Reminder[] {
    return [...this.rows.values()]
      .filter((r) => r.planDate === date)
      .sort((a, b) => (a.sendAt < b.sendAt ? -1 : a.sendAt > b.sendAt ? 1 : a.key < b.key ? -1 : 1))
      .map((r) => ({ ...r }));
  }

  byAutopay(autopayId: string): Reminder[] {
    return [...this.rows.values()].filter((r) => r.autopayId === autopayId).map((r) => ({ ...r }));
  }

  remove(key: string): void {
    this.rows.delete(key);
  }
}
import { isLocalDateTime, LocalDateTime } from "../time/localTime";

/** 자동이체(정기 출금) 계약 — 가맹점이 정한 날·시각에 출금된다. */
export interface Autopay {
  id: string;
  memberId: string;
  merchant: string;
  amount: number;
  /** 매월 출금일(1~28) */
  billingDay: number;
  /** 가맹점 출금 배치 시각 "HH:MM" */
  billingTime: string;
  active: boolean;
}

/** 출금 실패 기록 — 재출금은 실패 처리 시각 기준으로 잡힌다. */
export interface BillingFailure {
  autopayId: string;
  failedAt: LocalDateTime;
  reason: string;
}

export function validateAutopay(input: unknown): Omit<Autopay, "id" | "active"> {
  const b = (input ?? {}) as Record<string, unknown>;
  if (typeof b.memberId !== "string") throw new Error("memberId required");
  if (typeof b.merchant !== "string" || b.merchant.trim() === "") throw new Error("merchant required");
  if (typeof b.amount !== "number" || !Number.isInteger(b.amount) || b.amount <= 0) throw new Error("amount must be a positive integer (KRW)");
  if (typeof b.billingDay !== "number" || !Number.isInteger(b.billingDay) || b.billingDay < 1 || b.billingDay > 28) {
    throw new Error("billingDay must be 1..28");
  }
  if (typeof b.billingTime !== "string" || !/^([01]\d|2[0-3]):[0-5]\d$/.test(b.billingTime)) throw new Error("billingTime must be HH:MM");
  return { memberId: b.memberId, merchant: b.merchant.trim(), amount: b.amount, billingDay: b.billingDay, billingTime: b.billingTime };
}

export function validateFailure(autopayId: string, input: unknown): BillingFailure {
  const b = (input ?? {}) as Record<string, unknown>;
  if (!isLocalDateTime(b.failedAt)) throw new Error("failedAt must be YYYY-MM-DDTHH:MM:SS");
  const reason = typeof b.reason === "string" && b.reason !== "" ? b.reason : "INSUFFICIENT_BALANCE";
  return { autopayId, failedAt: b.failedAt, reason };
}
import { mkdtempSync, rmSync } from "fs";
import { tmpdir } from "os";
import { join } from "path";
import { App, createApp } from "../src/app";
import { assert, eq, onCleanup, run, test } from "./harness";

interface Report {
  planned: number;
  delivered: number;
  missing: number;
  pending: number;
  lines: { key: string; memberId: string; kind: string; status: string; sendAt: string }[];
  text: string;
}

interface Notifications {
  memberId: string;
  notifications: { at: string; tag: string; message: string }[];
}

/** 빈 pushq 상태 디렉토리를 가진 앱 하나 */
function world() {
  const home = mkdtempSync(join(tmpdir(), "autopay-rmd-"));
  onCleanup(() => rmSync(home, { recursive: true, force: true }));
  const app: App = createApp({ pushqHome: home, pushqBin: join(process.cwd(), "vendor", "bin", "pushq") });

  const call = (method: string, url: string, body?: unknown): unknown => {
    const r = app.handle(method, url, body);
    eq(r.status, 200, `${method} ${url} → ${JSON.stringify(r.body)}`);
    return r.body;
  };

  return {
    member(id: string, name: string, device: string, leadMinutes: number, pushOptIn = true): void {
      call("POST", "/members", { id, name, device, leadMinutes, pushOptIn });
    },
    autopay(memberId: string, merchant: string, amount: number, billingDay: number, billingTime: string): string {
      return (call("POST", "/autopays", { memberId, merchant, amount, billingDay, billingTime }) as { id: string }).id;
    },
    plan(date: string): { planned: number; scheduled: number; alreadyScheduled: number; skippedOptOut: number } {
      return call("POST", "/reminders/plan", { date }) as { planned: number; scheduled: number; alreadyScheduled: number; skippedOptOut: number };
    },
    fail(autopayId: string, failedAt: string): void {
      call("POST", `/autopays/${autopayId}/failures`, { failedAt });
    },
    cancel(autopayId: string): void {
      call("POST", `/autopays/${autopayId}/cancel`);
    },
    clock(until: string): void {
      call("POST", "/clock", { until });
    },
    report(date: string): Report {
      return call("GET", `/reports/reminders/${date}`) as Report;
    },
    inbox(memberId: string): Notifications["notifications"] {
      return (call("GET", `/members/${memberId}/notifications`) as Notifications).notifications;
    },
  };
}

test("every autopay customer gets the withdrawal reminder in time on billing day", () => {
  const w = world();
  w.member("M1001", "김하늘", "ios:Hb7cQ2xk91ZpA", 30);
  w.member("M1002", "이도윤", "and:fT0p3LmQw8eR", 60);
  w.member("M1003", "박서연", " IOS:Zx81kQpLm0Ty ", 30);
  w.member("M1004", "최민준", "and:Pq19sXkLm2Vb", 10);
  w.member("M1005", "정지우", "ios:Nn41tRe7Ku3Q", 1440);

  const phone = w.autopay("M1001", "한빛모바일 통신요금", 55000, 12, "08:00");
  w.autopay("M1002", "든든손해보험", 89000, 12, "10:20");
  w.autopay("M1003", "스트림플러스 구독", 13900, 12, "13:47");
  w.autopay("M1004", "푸른마을 관리비", 187420, 12, "18:33");
  w.autopay("M1005", "새싹수학학원", 320000, 12, "09:00");

  const plan = w.plan("2026-10-12");
  eq([plan.planned, plan.scheduled], [5, 5], "reminders planned for the 12th");

  // 08:00 출금이 잔액 부족으로 실패 → 2시간 뒤 재출금, 그 30분 전에 안내
  w.clock("2026-10-12T08:00:37");
  w.fail(phone, "2026-10-12T08:00:37");
  w.clock("2026-10-12T23:59:00");

  const r = w.report("2026-10-12");
  eq(r.lines.filter((l) => l.status !== "발송").map((l) => `${l.memberId} ${l.kind}`), [], "reminders not delivered");
  eq([r.planned, r.delivered, r.missing], [6, 6, 0], `report counts (${r.text})`);

  // 고객이 설정한 시점보다 늦게 도착하면 안 된다
  const latest: [string, string[], string][] = [
